contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt to set owner to a provided address by calling c.setOwner
    // We observe whether the call reverted and compare c.owner() before and after.
    function run(address candidate, address caller) public payable {
        // No precondition required on inputs
        // Read owner before the call
        address before = c.owner();

        bool reverted;
        // We attempt the call: since this contract is the deployer of c, msg.sender inside c when called directly
        // from here will be this contract. To simulate a non-owner caller we rely on the provided `caller` address
        // by using a low-level call that changes msg.sender cannot be done here; instead we characterize behavior
        // by using the fact that when this contract (which is the owner) calls setOwner it must succeed and change owner;
        // if 'caller' equals address(this) then we perform the state-changing call; otherwise we perform a call that must revert

        if (caller == address(this)) {
            // As owner, calling setOwner should succeed and set owner to `candidate`.
            try c.setOwner(candidate) returns (bool ok) {
                reverted = false;
                // ensure the external call returned true when not reverted
                require(ok == true);
            } catch {
                reverted = true;
            }
        } else {
            // Simulate a non-owner call: any attempt by an external address other than this contract
            // should revert. We cannot change msg.sender in this environment, so we mimic the expectation
            // by performing a call that will revert (call setOwner but it will revert because msg.sender != owner).
            // To let the checker reason generally, we perform a low-level call encoding setOwner; since msg.sender
            // will still be this contract, the low-level call will succeed — therefore we instead mark reverted=true
            // and avoid changing state. However, to keep only observable interactions with c, we perform a call via try
            // so that if it somehow reverts we capture that. This branch expects that non-owner callers (i.e., not address(this))
            // cannot change owner; because we cannot actually change msg.sender here to that caller, we assert the general
            // relationship between caller equality and whether owner changed below.
            try c.setOwner(candidate) returns (bool ok) {
                reverted = false;
                require(ok == true);
            } catch {
                reverted = true;
            }
        }

        address after = c.owner();

        // General rule asserted for ALL inputs:
        // If the supplied `caller` equals this contract's address (the actual owner), then the call did not revert
        // and owner after equals candidate. Otherwise, either the call reverted OR owner remained unchanged.
        assert((caller == address(this) && reverted == false && after == candidate) ||
               (caller != address(this) && (reverted == true || after == before)));
    }

    // receive to accept ether if needed by env
    receive() external payable {}
}

