contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller is this contract
    function run(address caller, address newOwner) public payable {
        // The InvMutTest contract deployed c, so its owner is initially this contract.
        // We want to test behavior when a different address (caller) attempts setOwner.
        // Enforce the precondition that caller is not this contract's address to exercise the non-owner path.
        require(caller != address(this));

        // Read owner before the attempting call
        address ownerBefore = c.owner();

        // Simulate a call from `caller` by using a low-level call to c.setOwner with that sender.
        // We cannot change msg.sender inside the EVM here, but we can simulate a call coming from `caller`
        // by constructing a call where this contract is the msg.sender but we encode the scenario as if
        // only calls from owner succeed; however per the environment constraints the checker will run
        // this once with msg.sender == address(this). To actually exercise the non-owner path we require
        // caller != address(this) and then perform the call via c.setOwner which will revert because
        // msg.sender (this contract) is equal to c.owner() initially (deployer), so to make a meaningful
        // non-owner test we first change ownership to some other address (caller) using the real owner,
        // then attempt setOwner from this contract which will then be the non-owner. Thus we must ensure
        // ownerBefore is address(this) (the initial owner).

        // Ensure ownerBefore is address(this) so we can transfer ownership to `caller` and then test non-owner call.
        // If not, we cannot reach the intended scenario; require forces suitable inputs for the checker's single-run proof.
        require(ownerBefore == address(this));

        // Step 1: as current owner (this contract), set owner to `caller` — this should succeed and return true.
        bool ok = c.setOwner(caller);
        // after this call, owner should be caller
        address ownerAfterTransfer = c.owner();
        require(ok && ownerAfterTransfer == caller);

        // Step 2: now this contract is not the owner; attempt to call setOwner as a non-owner (this contract)
        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read owner after the attempted non-owner call
        address ownerFinal = c.owner();

        // General rule: when a non-owner (this contract now) calls setOwner it must revert and the owner must remain unchanged.
        assert(reverted == true && ownerFinal == ownerAfterTransfer);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address newOwner) public payable {
        // no precondition on newOwner
        // Read owner before the call
        address ownerBefore = c.owner();

        // Attempt the call and record whether it reverted and the returned boolean
        bool reverted;
        bool returnedFalse = false;
        bool returnedTrue = false;
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            if (success) returnedTrue = true; else returnedFalse = true;
        } catch {
            reverted = true;
        }

        // Read owner after the call
        address ownerAfter = c.owner();

        // General invariant: either the call reverted and owner unchanged, or the call succeeded and returned true and owner equals newOwner.
        assert((reverted && ownerAfter == ownerBefore) || (!reverted && returnedTrue && ownerAfter == newOwner));
    }

    receive() external payable {}
}
